-- Tanda letras 1 (revisión 2026-10-18): 97 explicaciones que no nombraban las cuatro letras, usaban mayúsculas de énfasis
-- o guiones largos -> texto nuevo. Las de 'controversia' conservan su marca; las demás pasan a 'revisada'.
-- Guarda md5 por fila sobre el texto anterior; si no cuadran 97 actualizadas = 97 en el historial, ROLLBACK de todo.
BEGIN;
CREATE TEMP TABLE tc (id int, antes_md5 text, despues text) ON COMMIT DROP;
CREATE TEMP TABLE h0 ON COMMIT DROP AS SELECT count(*) n FROM explicaciones_historial;
SET LOCAL mir.motivo = 'Tanda letras 1 2026-10';
DO $$ DECLARE n int; h int; BEGIN
  WITH u AS (UPDATE preguntas p SET explicacion = tc.despues,
      explicacion_calidad = CASE WHEN p.explicacion_calidad = 'controversia' THEN 'controversia' ELSE 'revisada' END
    FROM tc WHERE p.id = tc.id AND md5(p.explicacion) = tc.antes_md5 AND p.anulada = false RETURNING 1)
  SELECT count(*) INTO n FROM u;
  SELECT (SELECT count(*) FROM explicaciones_historial) - h0.n INTO h FROM h0;
  IF n <> 97 OR h <> 97 THEN RAISE EXCEPTION 'actualizadas %, historial +% (esperado 97): ROLLBACK de todo', n, h; END IF;
  RAISE NOTICE 'actualizadas %, historial +%', n, h;
END $$;
COMMIT;
